(function(){
for(const key of Object.keys(localStorage)){if(key.startsWith('prayers:'))localStorage.removeItem(key);}
fetchPrayerDay=async function(date,coords){const key=`prayers:v13:${dateKey(date)}:${coords.latitude.toFixed(2)}:${coords.longitude.toFixed(2)}`;const cached=JSON.parse(localStorage.getItem(key)||'null');if(cached)return cached;const stamp=Math.floor(new Date(date.getFullYear(),date.getMonth(),date.getDate(),12).getTime()/1000);const url=`https://api.aladhan.com/v1/timings/${stamp}?latitude=${encodeURIComponent(coords.latitude)}&longitude=${encodeURIComponent(coords.longitude)}&method=13&school=0`;const response=await fetch(url);if(!response.ok)throw new Error(`Vakit kaynağı ${response.status}`);const json=await response.json();if(json.code!==200)throw new Error('Vakit verisi doğrulanamadı');const timings={};for(const [name] of prayerMap){const value=cleanTime(json.data.timings[name]);if(!value)throw new Error(`${name} vakti eksik`);timings[name]=value;}const value={timings,date:dateKey(date),timezone:json.data.meta?.timezone||'',method:'Türkiye · standart ikindi'};localStorage.setItem(key,JSON.stringify(value));return value;};
const hourlyToggle=document.querySelector('.hourly-toggle');if(hourlyToggle){hourlyToggle.textContent='⌄';hourlyToggle.setAttribute('aria-label','Saatlik ayeti aç');hourlyToggle.onclick=()=>{const card=hourlyToggle.closest('.hourly-verse');const open=card.classList.toggle('open');card.classList.toggle('collapsed',!open);hourlyToggle.textContent=open?'⌃':'⌄';hourlyToggle.setAttribute('aria-label',open?'Saatlik ayeti kapat':'Saatlik ayeti aç');hourlyToggle.setAttribute('aria-expanded',String(open));};}
const fullSurahSources={'ar.alafasy':'mishaari_raashid_al_3afaasee','ar.abdulbasitmurattal':'abdul_basit_murattal','ar.husary':'mahmood_khaleel_al-husaree','ar.minshawi':'muhammad_siddeeq_al-minshaawee','ar.abdurrahmaansudais':'abdurrahmaan_as-sudays','yasser-surah':'yasser_ad-dussary'};
const ayahEditions={'ar.alafasy':{edition:'ar.alafasy',bitrate:128},'ar.abdulbasitmurattal':{edition:'ar.abdulbasitmurattal',bitrate:192},'ar.husary':{edition:'ar.husary',bitrate:128},'ar.minshawi':{edition:'ar.minshawi',bitrate:128},'ar.abdurrahmaansudais':{edition:'ar.abdurrahmaansudais',bitrate:192}};
function fullSurahUrl(surah,id){return `https://download.quranicaudio.com/quran/${fullSurahSources[id]||fullSurahSources['ar.alafasy']}/${String(surah.number).padStart(3,'0')}.mp3`;}
function ayahAudioUrl(surah,ayah,id){if(id==='yasser-surah')return `https://everyayah.com/data/Yasser_Ad-Dussary_128kbps/${String(surah.number).padStart(3,'0')}${String(ayah.number).padStart(3,'0')}.mp3`;const cfg=ayahEditions[id]||ayahEditions['ar.alafasy'];return `https://cdn.islamic.network/quran/audio/${cfg.bitrate}/${cfg.edition}/${ayah.global}.mp3`;}
const playAll=$('play-arabic');if(playAll)playAll.onclick=()=>{const s=selectedSurah();if(!s)return;const id=$('arabic-reciter')?.value||'ar.alafasy',player=$('quran-audio');player.onended=null;player.onerror=null;player.src=fullSurahUrl(s,id);player.hidden=false;player.load();player.play().catch(()=>setStatus('Tam sure kaydı başlatılamadı. Bağlantıyı denetleyin.'));setStatus(`${s.name} suresi tek kayıt halinde oynatılıyor.`);};
const downloadAll=$('download-arabic');if(downloadAll)downloadAll.onclick=async()=>{const s=selectedSurah();if(!s)return;const id=$('arabic-reciter')?.value||'ar.alafasy',url=fullSurahUrl(s,id);downloadAll.disabled=true;try{const cache=await caches.open(`full-surah-${id}`);await cache.add(url);downloadAll.textContent='Kaydedildi';setStatus(`${s.name} suresinin tam kaydı çevrimdışı dinlemek için kaydedildi.`);}catch(_){setStatus('Tam sure kaydı indirilemedi.');}finally{downloadAll.disabled=false;setTimeout(()=>downloadAll.textContent='↓ Arapça indir',900);}};
function enhanceVerseCards(){const s=state.corpus?.surahs[state.selected-1];if(!s)return;const slug=s.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').replace(/[^a-zA-Z0-9]+/g,'-').replace(/^-|-$/g,'').toLowerCase();document.querySelectorAll('#verses .verse').forEach((card,index)=>{const ayah=s.ayahs[index],actions=card.querySelector('.verse-actions');if(!ayah||!actions)return;if(!actions.querySelector('[data-play-ayah]')){const audio=document.createElement('button');audio.type='button';audio.textContent='🔊';audio.title='Bu ayeti seçili kârîden dinle';audio.setAttribute('aria-label',`${s.name} ${ayah.number}. ayeti dinle`);audio.dataset.playAyah=String(ayah.number);actions.prepend(audio);}if(!card.querySelector('.tafsir-toggle')){const button=document.createElement('button');button.type='button';button.className='tafsir-toggle';button.textContent='Tefsiri göster';button.dataset.tafsir=String(ayah.number);const box=document.createElement('div');box.className='tafsir-box';box.hidden=true;box.innerHTML=`<strong>Kur’an Yolu Tefsiri</strong><p>Bu ayetin açıklamasını Diyanet İşleri Başkanlığı’nın Kur’an Yolu tefsirinde görüntüleyebilirsiniz.</p><a href="https://kuran.diyanet.gov.tr/mushaf/kuran-tefsir-1/${slug}-suresi-${s.number}/ayet-${ayah.number}/diyanet-isleri-baskanligi-meali-1" target="_blank" rel="noopener">${s.name} ${ayah.number}. ayet tefsirini aç ↗</a>`;card.append(button,box);}});}
const originalRenderReader=renderReader;renderReader=function(target){originalRenderReader(target);enhanceVerseCards();};enhanceVerseCards();
const verses=$('verses');if(verses)verses.addEventListener('click',event=>{const audio=event.target.closest('[data-play-ayah]');if(audio){event.preventDefault();event.stopPropagation();const s=selectedSurah(),ayah=s?.ayahs[Number(audio.dataset.playAyah)-1];if(!s||!ayah)return;const id=$('arabic-reciter')?.value||'ar.alafasy',player=$('quran-audio');player.onended=null;player.onerror=null;player.src=ayahAudioUrl(s,ayah,id);player.hidden=false;player.load();player.play().catch(()=>setStatus('Ayet sesi başlatılamadı.'));setStatus(`${s.name} ${ayah.number}. ayet seçili kârîden oynatılıyor.`);return;}const toggle=event.target.closest('[data-tafsir]');if(toggle){const box=toggle.nextElementSibling,open=box.hidden;box.hidden=!open;toggle.textContent=open?'Tefsiri gizle':'Tefsiri göster';}});
setTimeout(()=>{if(appState.location)loadPrayerTimes(appState.location);else requestLocation();},500);
})();
